"use strict";(globalThis.webpackChunkdocusaurus_resource=globalThis.webpackChunkdocusaurus_resource||[]).push([[6833],{19463:e=>{e.exports=JSON.parse('{"tag":{"label":"accessibility-testing","permalink":"/accessibility-hub/docs/tags/accessibility-testing","allTagsPath":"/accessibility-hub/docs/tags","count":12,"items":[{"id":"hot-topics/accessibility-audit","title":"Accessibility Audit","description":"Accessibility Audit covers the process and tools for evaluating digital content for accessibility compliance. This page will be expanded and curated with more detailed guidance and resources in the future.","permalink":"/accessibility-hub/docs/hot-topics/accessibility-audit"},{"id":"hot-topics/accessibility-testing","title":"Accessibility Testing","description":"An overview of accessibility testing: what automated scanners catch, what they miss, and the manual and code-based tests that fill the gap.","permalink":"/accessibility-hub/docs/hot-topics/accessibility-testing"},{"id":"for-developers/accessible-api-design-guide","title":"Accessible API Design for Developers","description":"Accessibility in software is often associated with user interfaces, but it is equally important in API and schema design. Accessible APIs improve usability for developers using assistive technologies, enhance code readability, and support better tooling integration. This guide outlines key strategies Java developers can adopt to make their APIs more inclusive.","permalink":"/accessibility-hub/docs/for-developers/accessible-api-design-guide"},{"id":"for-developers/ai-agents-read-your-accessibility-tree","title":"AI Agents Read Your Accessibility Tree, Not Your HTML","description":"A Spring Boot app served in two variants with identical backend and CSS but different markup, and what that one difference does to screen readers and AI agents.","permalink":"/accessibility-hub/docs/for-developers/ai-agents-read-your-accessibility-tree"},{"id":"hot-topics/bug-bounty","title":"Bug Bounty","description":"Bug Bounty programs encourage the discovery and reporting of accessibility issues. More curated content and examples will be added to this page in the future.","permalink":"/accessibility-hub/docs/hot-topics/bug-bounty"},{"id":"for-developers/case-studies","title":"Developer Case Studies","description":"Real accessibility experiments and fixes from developers: what was built, how it was tested, what broke, and what fixed it.","permalink":"/accessibility-hub/docs/for-developers/case-studies"},{"id":"for-developers/external-resources","title":"External Resources for Developers","description":"A curated list of the standards, guides, testing tools and learning resources developers actually need for accessibility work, grouped by what you\'re trying to do.","permalink":"/accessibility-hub/docs/for-developers/external-resources"},{"id":"resources/free-oss-resources","title":"Guides, Open source Tools and Patterns","description":"A curated list of high-quality, no-cost guides, tools, and patterns.","permalink":"/accessibility-hub/docs/resources/free-oss-resources"},{"id":"for-developers/how-to-contribute","title":"How to contribute","description":"Developers play a crucial role in making the world more accessible by designing and building digital experiences that are inclusive of people with disabilities. Here are several impactful ways developers can contribute:","permalink":"/accessibility-hub/docs/for-developers/how-to-contribute"},{"id":"resources/learning-paths/quickstart-guide","title":"Quickstart Guide with FOSS","description":"This plan is designed to get you hands-on with core accessibility concepts in one week, using freely available, and wherever possible, open-source tools.","permalink":"/accessibility-hub/docs/resources/learning-paths/quickstart-guide"},{"id":"for-developers/test-what-scanners-miss","title":"Test What Scanners Miss","description":"Why a high Lighthouse score is not a tested page, and the layers of testing that do catch the defects that block screen reader users and AI agents \u2014 with Java recipes for axe-core, role-based locators, aria snapshots and keyboard tests.","permalink":"/accessibility-hub/docs/for-developers/test-what-scanners-miss"},{"id":"for-developers/what-to-do-next","title":"What to Do Next: Six Steps for Your Own App","description":"Six short steps to check your own app the way screen readers and AI agents see it \u2014 the accessibility tree, the keyboard, a screen reader, role-based tests, a scanner, and the WCAG rules behind the fixes.","permalink":"/accessibility-hub/docs/for-developers/what-to-do-next"}],"unlisted":false}}')}}]);